		private void OnSelectBrowsingPointItem() {
			if (gmsMode == GMSMode.Trade)
			{
				audioManager.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);
				onSelectPointData?.Invoke(null);
			}
			else if (GetPointDataModelByIndex(currentBrowsingPointDataIndex).HasData)
			{
				onSelectPointData?.Invoke(null);
				SetShowHistoryFlag(true);
				viewState = ViewState.BrowsingHistoryView;
				ShowHistoryList();
				browsingPointHistoryScrollView.SetInputEnabled(true);
				audioManager.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);
