		}
		private void OnRequiredHistoryDataItem(global::Dpr.GMS.AUIGMSScrollItem item) {
			UIBrowsingPointHistoryDataItem historyItem = item as UIBrowsingPointHistoryDataItem;
			GMSPointDataModel pointData = GetPointDataModelByIndex(currentBrowsingPointDataIndex);
			PointHistoryDataModel historyData = pointData.GetHistoryDataByIndex(historyItem.GetIndex());
			if (historyData == null)
			{
				historyItem.ShowEmptyDataItem(emptyDataNameSb.ToString());
				return;
			}
			string title = historyData.DataIndex == pointData.MarkIndex ? markDataTitleSb.ToString() : historyData.GetDateTimeStr();
			historyItem.ShowHistoryDataItem(title, historyData.GetMonsNickname(), historyData.GetParentName(), historyData.sendMonsIconSpr, historyData.receiveMonsIconSpr, historyData.receiveMonsSexIconSpr, historyData.receiveMonsLangIconSpr, historyData.receiveMonsParentLangIconSpr, historyData.IsNew);
